        mQuest = new String[]{"\u0111ang l\u00e0m", "\u0111\u00e3 xong"};
        mHelp = new String[][]{{"Ch\u00e0o m\u1eebng b\u1ea1n \u0111\u1ebfn v\u1edbi th\u1ebf gi\u1edbi c\u1ee7a c\u00e1c hi\u1ec7p s\u0129", "Sau \u0111\u00e2y l\u00e0 ph\u1ea7n h\u01b0\u1edbng d\u1eabn ng\u01b0\u1eddi ch\u01a1i m\u1edbi", "D\u00f9ng ph\u00edm 2 \u0111\u1ec3 \u0111i l\u00ean, 8 \u0111i xu\u1ed1ng, 4 khi qua tr\u00e1i v\u00e0 6 n\u1ebfu mu\u1ed1n sang ph\u1ea3i.", "B\u1ea1n c\u0169ng c\u00f3 th\u1ec3 s\u1eed d\u1ee5ng c\u00e1c ph\u00edm \u0111i\u1ec1u h\u01b0\u1edbng \u0111\u1ec3 di chuy\u1ec3n theo \u00fd m\u00ecnh", "Gi\u1edd b\u1ea1n h\u00e3y di chuy\u1ec3n \u0111\u1ebfn v\u1ecb tr\u00ed m\u00e0u v\u00e0ng tr\u00ean m\u00e0n h\u00ecnh"}, {"R\u1ea5t t\u1ed1t,ti\u1ebfp theo b\u1ea1n h\u00e3y d\u00f9ng ph\u00edm 5 ho\u1eb7c ph\u00edm ch\u1ecdn \u0111\u1ec3 \u0111\u00e1nh 1 con qu\u00e1i.", "D\u1ea5u m\u0169i t\u00ean ph\u00eda tr\u00ean ch\u00ednh l\u00e0 d\u1ea5u hi\u1ec7u nh\u1eadn bi\u1ebft b\u1ea1n \u0111ang nh\u1eafm t\u1edbi con qu\u00e1i \u0111\u00f3", "", "Gi\u1ebft 1 con qu\u00e1i c\u0169ng d\u1ec5 th\u00f4i \u0111\u00fang kh\u00f4ng n\u00e0o. Khi \u0111\u00e1nh v\u00e0o nh\u1eefng con qu\u00e1i b\u1ea1n s\u1ebd nh\u1eadn \u0111\u01b0\u1ee3c m\u1ed9t l\u01b0\u1ee3ng \u0111i\u1ec3m kinh nghi\u1ec7m.", "Ngo\u00e0i ra c\u00f2n c\u00f3 th\u1ec3 nh\u1eb7t \u0111\u01b0\u1ee3c v\u1eadt ph\u1ea9m n\u1eefa. Gi\u1edd h\u00e3y th\u1eed \u0111\u00e1nh v\u00e0i con qu\u00e1i \u0111\u1ec3 ki\u1ec3m ch\u1ee9ng nh\u00e9.", "", "V\u1eadt ph\u1ea9m b\u1ea1n nh\u1eb7t \u0111\u01b0\u1ee3c s\u1ebd c\u1ea5t v\u00e0o trong h\u00e0nh trang", "H\u00e3y v\u00e0o h\u00e0nh trang xem ta c\u00f3 g\u00ec trong \u0111\u1ea5y n\u00e0o", "\u0110\u1ec3 v\u00e0o \u0111\u00f3 b\u1ea1n h\u00e3y nh\u1ea5n ph\u00edm ch\u1ecdn tr\u00e1i", "Nh\u1ea5n ch\u1ecdn tr\u00e1i \u0111\u1ec3 v\u00e0o h\u00e0nh trang."}, {"\u0110\u00e2y l\u00e0 h\u00e0nh trang n\u01a1i c\u1ea5t gi\u1eef m\u1ecdi th\u1ee9 cho b\u1ea1n", "Hi\u1ec7n th\u1eddi b\u1ea1n \u0111ang c\u00f3 m\u1ed9t v\u00e0i b\u00ecnh m\u00e1u, n\u0103ng l\u01b0\u1ee3ng v\u00e0 c\u1ea3 1 v\u1eadt pham.", "H\u00e3y th\u1eed s\u1eed d\u1ee5ng b\u00ecnh m\u00e1u b\u1eb1ng c\u00e1ch di chuy\u1ec3n khung ch\u1ecdn m\u00e0u tr\u1eafng \u0111\u1ebfn b\u00ecnh m\u00e1u", "B\u1ea5m ph\u00edm ch\u1ecdn tr\u00e1i v\u00e0 ch\u1ecdn m\u1ee5c s\u1eed d\u1ee5ng", "Nh\u1ea5n ph\u00edm ch\u1ecdn v\u00e0 ch\u1ecdn s\u1eed d\u1ee5ng", "R\u1ea5t t\u1ed1t, ngo\u00e0i ra b\u1ea1n c\u00f2n c\u00f3 th\u1ec3 d\u00f9ng c\u00e1c b\u00ecnh m\u00e1u v\u00e0 n\u0103ng l\u01b0\u1ee3ng b\u1eb1ng m\u1ed9t c\u00e1ch n\u1eefa", "\u0110\u00f3 l\u00e0 g\u1eafn ch\u00fang v\u00e0o ph\u00edm t\u1eaft \u0111\u1ec3 c\u00f3 th\u1ec3 thao t\u00e1c nhanh", "H\u00e3y l\u1ea1i di chuy\u1ec3n khung ch\u1ecdn t\u1edbi b\u00ecnh m\u00e1u 1 l\u1ea7n n\u1eefa v\u00e0 nh\u1ea5n ch\u1ecdn.", "L\u1ea7n n\u00e0y th\u00ec h\u00e3y ch\u1ecdn g\u00e1n ph\u00edm v\u00e0 ch\u1ecdn 1 ph\u00edm m\u00e0 b\u1ea1n th\u1ea5y l\u00e0 thu\u1eadn tay nh\u1ea5t nha.", "Nh\u1ea5n ph\u00edm ch\u1ecdn v\u00e0 ch\u1ecdn m\u1ee5c g\u00e1n ph\u00edm", "Nh\u1ea5n ph\u00edm ch\u1ecdn v\u00e0 ch\u1ecdn m\u1ee5c g\u00e1n ph\u00edm", "Vi\u1ec7c s\u1eed d\u1ee5ng n\u0103ng l\u01b0\u1ee3ng c\u0169ng t\u01b0\u01a1ng t\u1ef1 nh\u01b0 th\u1ebf.", "B\u1ea1n h\u00e3y th\u1eed d\u00f9ng v\u00e0 g\u1eafn ph\u00edm khi c\u1ea7n thi\u1ebft nha."}, {"Trong h\u00e0nh trang c\u1ee7a b\u1ea1n c\u00f2n c\u00f3 th\u00eam 1 v\u1eadt ph\u1ea9m", "Ngo\u00e0i t\u00e1c d\u1ee5ng l\u00e0m \u0111\u1eb9p th\u00ec v\u1eadt ph\u1ea9m n\u00e0y c\u00f2n gi\u00fap b\u1ea1n m\u1ea1nh m\u1ebd h\u01a1n \u0111\u1ea5y", "Vi\u1ec7c mang n\u00f3 c\u0169ng t\u01b0\u01a1ng t\u1ef1 nh\u01b0 l\u00e0 s\u1eed d\u1ee5ng m\u00e1u", "Gi\u1edd b\u1ea1n th\u1eed \u0111eo n\u00f3 v\u00e0o nha", "Nh\u1ea5n ph\u00edm ch\u1ecdn r\u1ed3i ch\u1ecdn m\u1ee5c s\u1eed d\u1ee5ng", "C\u0169ng \u0111\u01a1n gi\u1ea3n th\u00f4i ph\u1ea3i kh\u00f4ng n\u00e0o.", "B\u1ea5t c\u1ee9 v\u1eadt ph\u1ea9m n\u00e0o b\u1ea1n m\u1eb7c tr\u00ean ng\u01b0\u1eddi s\u1ebd xu\u1ea5t hi\u1ec7n trong Trang b\u1ecb", "V\u00e0 \u0111\u00e2y ch\u00ednh l\u00e0 Trang b\u1ecb c\u1ee7a b\u1ea1n h\u00e3y ch\u1ecdn v\u00e0o \u0111\u1ec3 xem ta c\u00f3 g\u00ec n\u00e0o ", "Di chuy\u1ec3n khung ch\u1ecdn t\u1edbi \u0111\u00e2y"}, {"\u0110\u00e2y ch\u00ednh l\u00e0 ph\u1ea7n Trang b\u1ecb gi\u00fap cho b\u1ea1n bi\u1ebft \u0111\u01b0\u1ee3c m\u00ecnh \u0111ang c\u00f3 nh\u1eefng g\u00ec tr\u00ean ng\u01b0\u1eddi", "Ph\u1ea7n b\u00ean tr\u00e1i hi\u1ec3n th\u1ecb nh\u00e2n v\u1eadt v\u00e0 th\u00f4ng tin s\u1ee9c kh\u1ecfe,\u0111i\u1ec3m pk c\u1ee7a b\u1ea1n", "B\u00ean ph\u1ea3i l\u00e0 th\u00f4ng tin v\u1ec1 s\u00e1t th\u01b0\u01a1ng, ph\u00f2ng th\u1ee7 v\u00e0 % kh\u00e1ng b\u1ea1n \u0111ang c\u00f3", "C\u00f2n d\u01b0\u1edbi n\u00e0y l\u00e0 ch\u00ednh l\u00e0 c\u00e1c v\u1eadt ph\u1ea9m b\u1ea1n \u0111ang c\u00f3 tr\u00ean ng\u01b0\u1eddi", "Khi b\u1ea1n c\u00f3 m\u1ed9t m\u00f3n \u0111\u1ed3 trong H\u00e0nh trang v\u00e0 mu\u1ed1n m\u1eb7c v\u00e0o ng\u01b0\u1eddi", "B\u1ea1n c\u0169ng c\u00f3 th\u1ec3 v\u00e0o \u0111\u00e2y ch\u1ecdn \u0111\u00fang v\u1ecb tr\u00ed t\u01b0\u01a1ng \u1ee9ng v\u00e0 ch\u1ecdn thay \u0111\u1ed5i", "Ngo\u00e0i ra n\u00f3 c\u00f2n gi\u00fap b\u1ea1n so s\u00e1nh khi c\u00f3 nhi\u1ec1u m\u00f3n \u0111\u1ed3 c\u00f9ng lo\u1ea1i n\u1eefa", "H\u00e3y th\u1eed ch\u1ee9c n\u0103ng n\u00e0y khi b\u1ea1n nh\u1eb7t dc 1 v\u00e0i m\u00f3n \u0111\u1ed3 n\u00e0o \u0111\u00f3", "Gi\u1edd h\u00e3y tr\u1edf ra \u0111\u1ec3 ti\u1ebfp t\u1ee5c cu\u1ed9c phi\u00eau l\u01b0u th\u00f4i", "Nh\u1ea5n ph\u00edm ch\u1ecdn ph\u1ea3i \u0111\u1ec3 tho\u00e1t ra"}, {"", "\u0110\u00e2y l\u00e0 b\u1ea3n \u0111\u1ed3 nh\u1ecf gi\u00fap b\u1ea1n c\u00f3 1 g\u00f3c nh\u00ecn l\u1edbn h\u01a1n v\u1ec1 khu v\u1ef1c \u0111ang \u0111\u1ee9ng", "H\u00e3y ch\u00fa \u00fd \u0111\u1ebfn \u0111i\u1ec3m ch\u1edbp m\u00e0u v\u00e0ng tr\u00ean b\u1ea3n \u0111\u1ed3 \u0111\u00f3 ch\u00ednh l\u00e0 n\u01a1i b\u1ea1n c\u1ea7n \u0111\u1ebfn", "Ph\u1ea7n th\u00f4ng tin v\u1ec1 m\u00e1u, n\u0103ng l\u01b0\u1ee3ng, c\u1ea5p \u0111\u1ed9 c\u1ee7a b\u1ea1n l\u00e0 \u0111\u00e2y.", "Khi b\u1ea1n ch\u1ecdn \u0111\u1ebfn 1 m\u1ee5c ti\u00eau n\u00e0o \u0111\u00f3 th\u00ec th\u00f4ng tin m\u1ee5c ti\u00eau s\u1ebb hi\u1ec7n \u1edf \u0111\u00e2y.", "N\u1ebfu mu\u1ed1n thay \u0111\u1ed5i m\u1ee5c ti\u00eau b\u1ea1n ch\u1ec9 c\u1ea7n nh\u1ea5n ph\u00edm ch\u1ecdn ph\u1ea3i.", "B\u1ea1n c\u00f3 \u0111\u1ebfn 2 thanh k\u1ef9 n\u0103ng h\u00e3y d\u00f9ng ph\u00edm 0 thay \u0111\u1ed5i", "Ph\u00edm * d\u00f9ng \u0111\u1ec3 chat v\u00e0 ph\u00edm # s\u1ebd gi\u00fap b\u1ea1n m\u1edf ph\u1ea7n s\u1ef1 ki\u1ec7n c\u1ee7a m\u00ecnh."}, {"B\u1ea1n v\u1eeba l\u00ean \u0111\u01b0\u1ee3c 1 c\u1ea5p, v\u00e0 s\u1ebd c\u00f3 r\u1ea5t nhi\u1ec1u \u0111i\u1ec1u hay ho khi l\u00ean c\u1ea5p m\u00e0 b\u1ea1n c\u1ea7n ph\u1ea3i bi\u1ebft", "Gi\u1edd th\u00ec h\u00e3y v\u00e0o H\u00e0nh Trang - Nh\u00e2n v\u1eadt xem n\u00e0o.", "Nh\u1ea5n ch\u1ecdn tr\u00e1i \u0111\u1ec3 v\u00e0o h\u00e0nh trang"}, {"\u0110\u00e2y l\u00e0 ph\u1ea7n Th\u00f4ng tin n\u01a1i cung c\u1ea5p cho b\u1ea1n m\u1ecdi th\u1ee9 v\u1ec1 ch\u1ec9 s\u1ed1 c\u1ee7a b\u1ea3n th\u00e2n", "\u0110\u00e2y l\u00e0 4 m\u1ee5c S\u1ee9c m\u1ea1nh, Kh\u00e9o l\u00e9o, Th\u1ec3 l\u1ef1c, Tin th\u1ea7n.", "M\u1ed7i l\u1ea7n l\u00ean c\u1ea5p th\u00ec m\u1ed5i m\u1ee5c s\u1ebd \u0111\u01b0\u1ee3c c\u1ed9ng th\u00eam 1 \u0111i\u1ec3m", "Ngo\u00e0i ra b\u1ea1n s\u1ebd c\u00f3 5 \u0111i\u1ec3m \u0111\u1ec3 c\u1ed9ng th\u00eam v\u00e0o, v\u00e0 c\u1ed9ng v\u00e0o \u0111\u00e2u, \u0111\u00fang hay sai do ch\u00ednh b\u1ea1n quy\u1ebft \u0111\u1ecbnh.", "Ph\u1ea7n b\u00ean d\u01b0\u1edbi ch\u00ednh l\u00e0 to\u00e0n b\u1ed9 th\u00f4ng tin v\u1ec1 ch\u1ec9 s\u1ed1 c\u1ee7a b\u1ea1n", "Gi\u1edd ta h\u00e3y th\u1eed c\u1ed9ng v\u00e0o S\u1ee9c Kh\u1ecfe v\u00e0i \u0111i\u1ec3m \u0111\u1ec3 th\u1ea5y s\u1ef1 thay \u0111\u1ed5i.", "Di chuy\u1ec3n t\u1edbi \u0111\u00e2y v\u00e0 nh\u1ea5n ch\u1ecdn", "R\u1ea5t t\u1ed1t, ch\u1ec9 s\u1ed1 c\u1ee7a b\u1ea1n \u0111\u00e3 t\u0103ng l\u00ean 1 \u00edt r\u1ed3i.", "Khi l\u00ean c\u1ea5p th\u00ec k\u1ef9 n\u0103ng c\u1ee7a b\u1ea1n c\u0169ng \u0111\u01b0\u1ee3c n\u00e2ng cao, h\u00e3y v\u00e0o xem th\u1eed n\u00e0o.", "Di chuy\u1ec3n khung ch\u1ecdn t\u1edbi \u0111\u00e2y"}, {"\u0110\u00e2y l\u00e0 ph\u1ea7n K\u1ef9 N\u0103ng, n\u01a1i cho b\u1ea1n bi\u1ebft t\u1ea5t c\u1ea3 c\u00e1c tuy\u1ec7t chi\u00eau m\u00ecnh c\u00f3 th\u1ec3 h\u1ecdc.", "C\u00e1c d\u00e3y b\u00ean tr\u00e1i l\u00e0 k\u1ef9 n\u0103ng V\u1eadt l\u00fd", "Khi mu\u1ed1n bi\u1ebft th\u00f4ng tin v\u1ec1 k\u1ef9 n\u0103ng \u0111\u00f3 b\u1ea1n ch\u1ec9 c\u1ea7n ch\u1ecdn v\u00e0o n\u00f3.", "B\u00ean ph\u1ea3i l\u00e0 c\u00e1c k\u1ef9 n\u0103ng ma thu\u1eadt.", "M\u1ed7i khi l\u00ean 1 c\u1ea5p b\u1ea1n s\u1ebd c\u00f3 1 \u0111i\u1ec3m k\u1ef9 n\u0103ng \u0111\u1ec3 c\u1ed9ng v\u00e0o", "V\u00e0 c\u0169ng nh\u01b0 \u0111i\u1ec3m ti\u1ec1m n\u0103ng c\u1ed9ng v\u00e0o \u0111\u00e2u \u0111\u00f3 l\u00e0 t\u00f9y quy\u1ebft \u0111\u1ecbnh c\u1ee7a b\u1ea1n.", "Gi\u1edd h\u00e3y c\u1ed9ng v\u00e0o 1 k\u1ef9 n\u0103ng, nh\u1edb xem k\u1ef9 th\u00f4ng tin xem b\u1ea1n th\u00edch h\u1ee3p v\u1edbi c\u00e1i n\u00e0o h\u01a1n nha.", "Ch\u1ecdn v\u00e0o 1 k\u1ef9 n\u0103ng r\u1ed3i nh\u1ea5n c\u1ed9ng \u0111i\u1ec3m", "\u0110\u01b0\u1ee3c r\u1ed3i,v\u00e0 c\u0169ng nh\u01b0 b\u00ecnh m\u00e1u b\u1ea1n c\u00f3 th\u1ec3 g\u00e1n v\u00e0o ph\u00edm \u0111\u1ec3 s\u1eed d\u1ee5ng nhanh.", "H\u00e3y g\u00e1n v\u00e0o 1 ph\u00edm n\u00e0o \u0111\u00f3 r\u1ed3i ra ngo\u00e0i ki\u1ec3m tra s\u1ee9c m\u1ea1nh c\u1ee7a n\u00f3 xem sao.", ""}, {"B\u1ea1n v\u1eeba nh\u1eadn m\u1ed9t nhi\u1ec7m v\u1ee5 m\u1edbi,h\u00e3y v\u00e0o H\u00e0nh Trang - Nh\u00e2n v\u1eadt \u0111\u1ec3 xem l\u1ea1i th\u00f4ng tin nhi\u1ec7m v\u1ee5 \u0111\u00f3 n\u00e0o.", "Di chuy\u1ec3n khung ch\u1ecdn t\u1edbi \u0111\u00e2y", "\u0110\u00e2y ch\u00ednh l\u00e0 m\u1ee5c nhi\u1ec7m v\u1ee5 gi\u00fap b\u1ea1n qu\u1ea3n l\u00fd th\u00f4ng tin nhi\u1ec7m v\u1ee5 c\u1ee7a m\u00ecnh", "Th\u1ebb b\u00ean tr\u00e1i l\u00e0 t\u1ed5ng h\u1ee3p t\u1ea5t c\u1ea3 nhi\u1ec7m v\u1ee5 b\u1ea1n \u0111ang l\u00e0m.", "Th\u1ebb b\u00ean ph\u1ea3i l\u00e0 c\u00e1c nhi\u1ec7m v\u1ee5 \u0111\u00e3 xong v\u00e0 c\u00f3 th\u1ec3 tr\u1ea3.", "Khi mu\u1ed1n bi\u1ebft th\u00eam th\u00f4ng tin v\u1ec1 nhi\u1ec7m v\u1ee5 n\u00e0o \u0111\u00f3 ch\u1ec9 c\u1ea7n b\u1ea1n di chuy\u1ec3n m\u1ee5c ch\u1ecdn t\u1edbi \u0111\u00f3, r\u1ed3i nh\u1ea5n xem.", "B\u1ea1n c\u0169ng c\u00f3 th\u1ec3 xem ph\u1ea7n b\u1ea3n \u0111\u1ed3 l\u1edbn \u0111\u1ec3 bi\u1ebft r\u00f5 h\u01a1n v\u1ec1 v\u1ecb tr\u00ed hi\u1ec7n t\u1ea1i c\u0169ng nh\u01b0 n\u1edbi c\u1ea7n ph\u1ea3i \u0111\u1ebfn.", ""}};
